const sleep=ms=>new Promise(r=>setTimeout(r,ms));const tab=await(await fetch('http://127.0.0.1:9222/json/new?http://127.0.0.1:4173/',{method:'PUT'})).json();const ws=new WebSocket(tab.webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let n=1;const p=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){p.get(m.id)(m);p.delete(m.id)}};const call=(method,params={})=>new Promise(r=>{let id=n++;p.set(id,r);ws.send(JSON.stringify({id,method,params}))});const ev=async expression=>(await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true})).result.result.value;await call('Page.enable');await call('Runtime.enable');await call('Network.enable');await sleep(1000);for(let i=0;i<20;i++){if(await ev('!!navigator.serviceWorker.controller'))break;await sleep(250)}await call('Network.emulateNetworkConditions',{offline:true,latency:0,downloadThroughput:0,uploadThroughput:0,connectionType:'none'});for(const route of ['/','/forms','/files','/merged-files','/spreadsheet','/settings']){await call('Page.navigate',{url:'http://127.0.0.1:4173'+route});await sleep(1600);console.log(route,JSON.stringify(await ev("({h1:document.querySelector('h1')?.innerText||document.querySelector('[role=heading]')?.innerText||'',title:document.title,ready:document.readyState,controlled:!!navigator.serviceWorker.controller,bodyEnd:document.body.innerText.slice(-110)})")))}ws.close();
